// Rule `effect-agreement` (spec 0002, F2 for a decoded Plan): the cross-references of a Plan's effects hold whatever
// produced the Plan. The source parser already refuses each of these (`validateScene` in `@reebeat/core`); the rule
// reads the Plan itself, so a `plan.json` that was edited or generated by another tool is held to the same rules:
// a `show` or `focus` names an Element of its Scene, a `show` names one that is `visible=false`, every
// `visible=false` Element is shown exactly once, a `sound` has a name and no target, and a `show` or `focus` has a
// target and no name; ids are unique in their scope.
import type { Effect, PlanJson, Scene } from "@reebeat/core";
import { Array as Arr, Option } from "effect";

import type { Diagnostic } from "./diagnostic.ts";

export const effectAgreementRule = "effect-agreement";

const at = (
  scene: Scene,
  line: number,
  message: string
): readonly Diagnostic[] => [
  {
    line,
    message: `scene ${scene.id}: ${message}`,
    rule: effectAgreementRule,
    sceneId: scene.id,
  },
];

const argumentsOf = (scene: Scene, effect: Effect): readonly Diagnostic[] => {
  if (effect.verb === "sound") {
    return effect.name === undefined || effect.target !== undefined
      ? at(
          scene,
          effect.line,
          `effect ${effect.id} is a sound: expected a name and no target`
        )
      : [];
  }

  return effect.target === undefined || effect.name !== undefined
    ? at(
        scene,
        effect.line,
        `effect ${effect.id} is a ${effect.verb}: expected an Element target and no sound name`
      )
    : [];
};

const targetOf = (scene: Scene, effect: Effect): readonly Diagnostic[] => {
  const { target } = effect;

  if (target === undefined) {
    return [];
  }

  const element = Arr.findFirst(
    scene.elements,
    (candidate) => candidate.id === target
  );

  if (Option.isNone(element)) {
    return at(
      scene,
      effect.line,
      `effect ${effect.id} names Element "${target}", which the Scene does not have`
    );
  }

  return effect.verb === "show" && element.value.visible
    ? at(
        scene,
        effect.line,
        `effect ${effect.id} shows Element "${target}", which is visible`
      )
    : [];
};

const hiddenOf = (scene: Scene): readonly Diagnostic[] => {
  const hidden = Arr.filter(scene.elements, (candidate) => !candidate.visible);

  return Arr.flatMap(hidden, (element) => {
    const shows = Arr.filter(
      scene.effects,
      (effect) => effect.verb === "show" && effect.target === element.id
    );

    return shows.length === 1
      ? []
      : at(
          scene,
          element.line,
          `Element "${element.id}" is visible=false and is shown ${shows.length} times: expected exactly one show effect`
        );
  });
};

const duplicates = (scene: Scene): readonly Diagnostic[] =>
  Arr.flatMap(scene.effects, (effect, index) =>
    Arr.some(
      Arr.take(scene.effects, index),
      (earlier) => earlier.id === effect.id
    )
      ? at(scene, effect.line, `effect id "${effect.id}" is used twice`)
      : []
  );

/** The cross-reference problems of every Scene's effects. */
export const effectAgreement = (plan: PlanJson): readonly Diagnostic[] =>
  Arr.flatMap(plan.scenes, (scene) => [
    ...Arr.flatMap(scene.effects, (effect) => [
      ...argumentsOf(scene, effect),
      ...targetOf(scene, effect),
    ]),
    ...hiddenOf(scene),
    ...duplicates(scene),
  ]);
